sp_theme.css_variables:
/* ==========================================================================
   DSFR Theme - Design System de l'État français
   Conforme RGAA (accessibilité)
   ========================================================================== */

/* --- Variables principales DSFR --- */
$brand-primary: #000091 !default;
$brand-success: #18753C !default;
$brand-info: #0063CB !default;
$brand-warning: #B34000 !default;
$brand-danger: #CE0500 !default;

$brand-text-color: #161616 !default;
$brand-bg-light: #F5F5FE !default;

/* Navbar alignment */
$navbar-default-bg: #FFFFFF !default;
$navbar-default-border: #E5E5E5 !default;
$navbar-default-link-color: #161616 !default;
$navbar-default-link-hover-color: #000091 !default;
$navbar-default-link-active-color: #000091 !default;

/* --- Typographie Marianne --- */
$font-family-sans-serif: "Marianne", Arial, sans-serif !default;
$headings-font-family: "Marianne", Arial, sans-serif !default;
$font-size-base: 16px !default;
$line-height-base: 1.5 !default;

/* --- Focus RGAA --- */
$input-border-focus: #0A76F6 !default;

/* --- Boutons --- */
$btn-border-radius-base: 0px !default;
$btn-primary-bg: #000091 !default;
$btn-primary-color: #FFFFFF !default;

/* --- Liens --- */
$link-color: #000091 !default;
$link-hover-color: #1212FF !default;

/* --- Composants --- */
$panel-default-border: #E5E5E5 !default;
$panel-default-heading-bg: #F6F6F6 !default;

/* ==========================================================================
   Styles globaux
   ========================================================================== */

body {
  font-family: "Marianne", Arial, sans-serif;
  color: #161616;
  background-color: #F5F5FE;
}

/* Focus visible conforme RGAA */
*:focus-visible {
  outline: 2px solid #0A76F6 !important;
  outline-offset: 2px !important;
}

/* En-tête République Française */
.navbar-header .navbar-brand {
  font-family: "Marianne", Arial, sans-serif;
  font-weight: 700;
  color: #000091;
}

/* Boutons DSFR */
.btn-primary {
  background-color: #000091;
  border-color: #000091;
  color: #FFFFFF;
  border-radius: 0;
  &:hover, &:focus {
    background-color: #1212FF;
    border-color: #1212FF;
  }
}

.btn-default {
  border-color: #000091;
  color: #000091;
  border-radius: 0;
  &:hover, &:focus {
    background-color: #F5F5FE;
    border-color: #1212FF;
    color: #1212FF;
  }
}

/* Liens DSFR */
a {
  color: #000091;
  text-decoration: underline;
  &:hover, &:focus {
    color: #1212FF;
  }
}

/* Panels / Cards */
.panel {
  border-radius: 0;
  border-color: #E5E5E5;
  box-shadow: 0 2px 6px rgba(0, 0, 18, 0.08);
}

.panel-heading {
  border-radius: 0;
  background-color: #F6F6F6;
  border-bottom: 2px solid #000091;
}

/* Alertes DSFR */
.alert-info {
  background-color: #E8EDFF;
  border-color: #000091;
  color: #000091;
}

.alert-success {
  background-color: #B8FEC9;
  border-color: #18753C;
  color: #18753C;
}

.alert-warning {
  background-color: #FFE9E6;
  border-color: #B34000;
  color: #B34000;
}

.alert-danger {
  background-color: #FFE9E6;
  border-color: #CE0500;
  color: #CE0500;
}

/* Formulaires */
.form-control {
  border-radius: 0;
  border-color: #929292;
  &:focus {
    border-color: #0A76F6;
    box-shadow: 0 0 0 2px rgba(10, 118, 246, 0.25);
  }
}

/* Bannière REPUBLIQUE FRANCAISE */
.sp-header {
  border-top: 3px solid;
  border-image: linear-gradient(to right, #000091, #FFFFFF, #E1000F) 1;
}
